CREATE TABLE event_waitlist_settings(event_id TEXT PRIMARY KEY REFERENCES special_events(id),offer_minutes INTEGER NOT NULL DEFAULT 1440 CHECK(offer_minutes BETWEEN 15 AND 10080));
CREATE TABLE event_waitlist_challenges(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES special_event_ticket_products(id),name TEXT NOT NULL,email TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20),code_hash TEXT NOT NULL,verification_lease TEXT,attempts INTEGER NOT NULL DEFAULT 0,expires_at TEXT NOT NULL,consumed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE event_waitlist_entries(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,product_id TEXT NOT NULL REFERENCES special_event_ticket_products(id),name TEXT NOT NULL,email TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20),status TEXT NOT NULL DEFAULT 'WAITING' CHECK(status IN('WAITING','OFFERED','CHECKOUT','EXPIRED','LEFT','FULFILLED')),verified_joined_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE UNIQUE INDEX event_waitlist_active_unique ON event_waitlist_entries(product_id,email) WHERE status IN('WAITING','OFFERED','CHECKOUT');
CREATE TABLE event_waitlist_sessions(token_hash TEXT PRIMARY KEY,entry_id TEXT NOT NULL REFERENCES event_waitlist_entries(id),expires_at TEXT NOT NULL);
CREATE TABLE event_waitlist_offers(id TEXT PRIMARY KEY,entry_id TEXT NOT NULL UNIQUE REFERENCES event_waitlist_entries(id),hold_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'OFFERED' CHECK(status IN('OFFERED','CHECKOUT','EXPIRED','LEFT','FULFILLED')),expires_at TEXT NOT NULL,checkout_expires_at TEXT,override_reason TEXT,actor TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE event_waitlist_notifications(id TEXT PRIMARY KEY,booking_id TEXT,recipient_email TEXT NOT NULL,kind TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'READY' CHECK(status IN('READY','SENDING','SENT','RETRY','UNKNOWN_REVIEW')),attempts INTEGER NOT NULL DEFAULT 0,lease_id TEXT,leased_at TEXT,provider_id TEXT,next_attempt_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at TEXT);
-- All normal checkout and offer reservations use these same holds. Capacity is fenced in SQLite,
-- including when separate workers observe the same availability. Hold-day rows are inserted in the same batch.
CREATE TRIGGER event_hold_capacity_insert BEFORE INSERT ON special_event_holds WHEN NEW.status='ACTIVE' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM special_event_ticket_products p WHERE p.id=NEW.product_id AND p.event_id=NEW.event_id AND p.allocation IS NOT NULL AND NEW.quantity+coalesce((SELECT sum(effective_quantity) FROM event_effective_bookings WHERE product_id=p.id AND status='PAID'),0)+coalesce((SELECT sum(quantity) FROM special_event_holds WHERE product_id=p.id AND status='ACTIVE' AND julianday(expires_at)>julianday('now')),0)<=p.allocation) THEN RAISE(ABORT,'WAIT_PRODUCT_CAPACITY') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM special_event_product_days pd JOIN special_event_days d ON d.id=pd.day_id WHERE pd.product_id=NEW.product_id AND (d.capacity IS NULL OR NEW.quantity*pd.places_per_ticket+coalesce((SELECT sum(bd.places) FROM event_effective_booking_days bd JOIN special_event_bookings b ON b.id=bd.booking_id WHERE bd.day_id=d.id AND b.status='PAID'),0)+coalesce((SELECT sum(h.quantity*hp.places_per_ticket) FROM special_event_holds h JOIN special_event_product_days hp ON hp.product_id=h.product_id WHERE hp.day_id=d.id AND h.status='ACTIVE' AND julianday(h.expires_at)>julianday('now')),0)>d.capacity)) THEN RAISE(ABORT,'WAIT_DAY_CAPACITY') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM special_event_ticket_products p JOIN special_events e ON e.id=p.event_id WHERE p.id=NEW.product_id AND p.includes_saturday_evening=1 AND (e.saturday_evening_capacity IS NULL OR NEW.quantity+coalesce((SELECT sum(b.effective_quantity) FROM event_effective_bookings b JOIN special_event_ticket_products bp ON bp.id=b.product_id WHERE b.event_id=e.id AND b.status='PAID' AND bp.includes_saturday_evening=1),0)+coalesce((SELECT sum(h.quantity) FROM special_event_holds h JOIN special_event_ticket_products hp ON hp.id=h.product_id WHERE h.event_id=e.id AND h.status='ACTIVE' AND hp.includes_saturday_evening=1 AND julianday(h.expires_at)>julianday('now')),0)>e.saturday_evening_capacity)) THEN RAISE(ABORT,'WAIT_EVENING_CAPACITY') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM special_event_ticket_products p JOIN special_event_ticket_products mini ON mini.event_id=p.event_id AND mini.code='MINI_COMPETITION' WHERE p.id=NEW.product_id AND (CASE WHEN p.code='MINI_COMPETITION' THEN NEW.quantity ELSE NEW.competition_quantity END)>0 AND (mini.allocation IS NULL OR (CASE WHEN p.code='MINI_COMPETITION' THEN NEW.quantity ELSE NEW.competition_quantity END)+coalesce((SELECT count(*) FROM special_event_competition_entries c JOIN special_event_bookings b ON b.id=c.booking_id WHERE c.event_id=NEW.event_id AND c.status<>'WITHDRAWN' AND b.status='PAID'),0)+coalesce((SELECT sum(CASE WHEN hp.code='MINI_COMPETITION' THEN h.quantity ELSE h.competition_quantity END) FROM special_event_holds h JOIN special_event_ticket_products hp ON hp.id=h.product_id WHERE h.event_id=NEW.event_id AND h.status='ACTIVE' AND julianday(h.expires_at)>julianday('now')),0)>mini.allocation)) THEN RAISE(ABORT,'WAIT_COMPETITION_CAPACITY') END;
END;
CREATE TRIGGER event_offer_validate BEFORE INSERT ON event_waitlist_offers BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM event_waitlist_entries w JOIN special_event_ticket_products p ON p.id=w.product_id JOIN special_events e ON e.id=p.event_id WHERE w.id=NEW.entry_id AND w.status='WAITING' AND (p.release_state='ACTIVE' OR (p.release_state='SOLD_OUT' AND p.code NOT IN('EARLY_BIRD_WEEKEND','LOYALTY_WEEKEND'))) AND e.status='PUBLISHED' AND e.checkout_enabled=1 AND p.product_type='ADMISSION') THEN RAISE(ABORT,'WAIT_NOT_ELIGIBLE') END;
 SELECT CASE WHEN coalesce(length(trim(NEW.override_reason)),0)=0 AND EXISTS(SELECT 1 FROM event_waitlist_entries earlier JOIN event_waitlist_entries w ON w.product_id=earlier.product_id WHERE w.id=NEW.entry_id AND earlier.seq<w.seq AND earlier.status='WAITING') THEN RAISE(ABORT,'WAIT_FIFO_BLOCKED') END;
END;
CREATE TRIGGER event_offer_create AFTER INSERT ON event_waitlist_offers BEGIN
 INSERT INTO special_event_holds(id,event_id,product_id,customer_email,quantity,amount_pence,status,expires_at,idempotency_key)
 SELECT NEW.hold_id,p.event_id,p.id,w.email,w.quantity,p.price_pence*w.quantity,'ACTIVE',NEW.expires_at,'wait-offer:'||NEW.id FROM event_waitlist_entries w JOIN special_event_ticket_products p ON p.id=w.product_id WHERE w.id=NEW.entry_id;
 INSERT INTO special_event_hold_days(hold_id,day_id,places) SELECT NEW.hold_id,pd.day_id,w.quantity*pd.places_per_ticket FROM event_waitlist_entries w JOIN special_event_product_days pd ON pd.product_id=w.product_id WHERE w.id=NEW.entry_id;
 UPDATE event_waitlist_entries SET status='OFFERED' WHERE id=NEW.entry_id;
 INSERT INTO event_waitlist_notifications(id,recipient_email,kind,payload_json) SELECT 'offer:'||NEW.id,email,'WAITLIST_OFFER',json_object('expiry',NEW.expires_at,'quantity',quantity) FROM event_waitlist_entries WHERE id=NEW.entry_id;
 INSERT INTO special_event_activity(id,event_id,action,target_type,target_id,actor,reason,idempotency_key) SELECT NEW.id,p.event_id,CASE WHEN NEW.override_reason IS NULL THEN 'WAITLIST_FIFO_OFFER' ELSE 'WAITLIST_OWNER_OVERRIDE' END,'WAITLIST_OFFER',NEW.id,NEW.actor,coalesce(NEW.override_reason,'Strict FIFO offer reserved.'),'wait-offer:'||NEW.id FROM event_waitlist_entries w JOIN special_event_ticket_products p ON p.id=w.product_id WHERE w.id=NEW.entry_id;
END;
CREATE TRIGGER event_offer_accept BEFORE UPDATE OF status ON event_waitlist_offers WHEN NEW.status='CHECKOUT' AND OLD.status='OFFERED' BEGIN
 SELECT CASE WHEN julianday(OLD.expires_at)<=julianday('now') OR NOT EXISTS(SELECT 1 FROM event_waitlist_entries w JOIN special_event_ticket_products p ON p.id=w.product_id JOIN special_events e ON e.id=p.event_id JOIN special_event_holds h ON h.id=OLD.hold_id WHERE w.id=OLD.entry_id AND w.status='OFFERED' AND (p.release_state='ACTIVE' OR (p.release_state='SOLD_OUT' AND p.code NOT IN('EARLY_BIRD_WEEKEND','LOYALTY_WEEKEND'))) AND p.price_pence*w.quantity=h.amount_pence AND h.status='ACTIVE' AND e.status='PUBLISHED' AND e.checkout_enabled=1) THEN RAISE(ABORT,'WAIT_OFFER_EXPIRED_OR_CHANGED') END;
END;
CREATE TRIGGER event_offer_changed AFTER UPDATE OF status ON event_waitlist_offers WHEN NEW.status<>OLD.status BEGIN
 UPDATE event_waitlist_entries SET status=NEW.status WHERE id=NEW.entry_id;
 UPDATE special_event_holds SET expires_at=NEW.checkout_expires_at WHERE id=NEW.hold_id AND NEW.status='CHECKOUT';
 UPDATE special_event_holds SET status='RELEASED' WHERE id=NEW.hold_id AND status='ACTIVE' AND NEW.status IN('EXPIRED','LEFT');
END;
-- A verified paid checkout may fulfil only its current reserved offer. Old pending captures require manual review.
CREATE TRIGGER event_waitlist_payment_fence BEFORE UPDATE OF status ON special_event_bookings WHEN NEW.status='PAID' AND OLD.status<>'PAID' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM event_waitlist_offers WHERE hold_id=NEW.hold_id AND (status<>'CHECKOUT' OR julianday(checkout_expires_at)<=julianday('now'))) THEN RAISE(ABORT,'WAITLIST_LATE_PAYMENT_REVIEW') END;
END;
CREATE TRIGGER event_waitlist_paid AFTER UPDATE OF status ON special_event_bookings WHEN NEW.status='PAID' AND OLD.status<>'PAID' BEGIN
 UPDATE event_waitlist_offers SET status='FULFILLED' WHERE hold_id=NEW.hold_id AND status='CHECKOUT';
END;

CREATE TABLE event_waitlist_checkout_claims(hold_id TEXT PRIMARY KEY REFERENCES special_event_holds(id),operation_id TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
